declare(strict_types=1); require_once __DIR__.'/_guard.php'; dash_require('events'); dash_require_hq(); require_once __DIR__.'/../event-lib.php';$pdo=dash_pdo();$id=(int)($_GET['id']??0);$eventId=(int)($_GET['event_id']??0);$row=['id'=>0,'event_id'=>$eventId,'title'=>'','slug'=>'','excerpt'=>'','content'=>'','image'=>'','status'=>'draft'];if($id){$s=$pdo->prepare('SELECT * FROM event_news WHERE id=?');$s->execute([$id]);$row=$s->fetch()?:$row;}$events=$pdo->query("SELECT id,title FROM events WHERE status<>'archived' ORDER BY event_date DESC")->fetchAll();$PANEL_TITLE=$id?'ویرایش خبر رویداد':'خبر جدید رویداد';require __DIR__.'/_panel_head.php';
?><style>.event-news-form{max-width:900px;margin:auto}.event-news-form input,.event-news-form select,.event-news-form textarea{width:100%;border:1px solid var(--color-border);background:var(--color-bg);border-radius:11px;padding:11px 12px;font:inherit;color:var(--color-text)}.event-news-form textarea{min-height:280px;resize:vertical}.event-news-form label{display:grid;gap:7px;font-size:12px;font-weight:700}.news-cover{max-width:200px;border-radius:10px;margin-top:8px}</style><form class="event-news-form" method="post" action="event-news-save.php" enctype="multipart/form-data"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$row['id'] ?>"><div class="page-head"><div class="ph-ic">▤</div><div><h1><?= $id?'ویرایش خبر رویداد':'ساخت خبر اختصاصی' ?></h1><p>این خبر فقط در صفحه رویداد انتخاب‌شده نمایش داده می‌شود.</p></div></div><div class="card"><div class="grid2"><div class="field"><label>رویداد<select name="event_id" required><?php foreach($events as $e): ?><option value="<?= (int)$e['id'] ?>" <?= (int)$row['event_id']===(int)$e['id']?'selected':'' ?>><?= event_h($e['title']) ?></option><?php endforeach; ?></select></label></div><div class="field"><label>وضعیت<select name="status"><option value="draft" <?= $row['status']==='draft'?'selected':'' ?>>پیش‌نویس</option><option value="published" <?= $row['status']==='published'?'selected':'' ?>>منتشرشده</option></select></label></div></div><div class="field"><label>عنوان خبر<input type="text" name="title" required value="<?= event_h($row['title']) ?>"></label></div><div class="field"><label>خلاصه خبر<input type="text" name="excerpt" value="<?= event_h($row['excerpt']) ?>"></label></div><div class="field"><label>تصویر شاخص<input type="file" name="image" accept="image/*"><?php if($row['image']): ?><img class="news-cover" src="<?= event_h($row['image']) ?>" alt=""><?php endif; ?></label></div><div class="field"><label>متن خبر<textarea name="content" required><?= event_h($row['content']) ?></textarea></label></div></div><div class="actions"><button class="btn btn-primary" type="submit">ذخیره خبر</button><a class="btn btn-ghost" href="event-news-list.php">انصراف</a></div></form></div></body></html>
